<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
type Row=Record<string,any>
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,hosts:Row[]}>()
const emit=defineEmits(['changed'])
const services=ref<Row[]>([]),nodes=ref<Row[]>([]),templates=ref<Row[]>([]),certificates=ref<Row[]>([]),proxies=ref<Row[]>([]),catalog=ref<Row[]>([])
const tab=ref('nodes'),hostFilter=ref(''),busy=ref(false),error=ref(''),notice=ref(''),editing=ref(''),preview=ref<any>(null),confirm=ref<Row|null>(null)
const fresh=()=>({password:'',uuid:'',name:'',host_id:'',node_id:'',engine:'sing-box',kind:'shadowsocks',address:'',listen:'127.0.0.1',port:2080,transport:'tcp',path:'',tls_mode:'tls',server_name:'',certificate_id:'',certificate:'',private_key:'',next_id:'',parent_id:'',tunnels:[] as Row[],version:0,rotate_credentials:false})
const form=ref(fresh()),showForm=ref(false)
const certForm=ref({domain:'',email:'',provider:'http-01',dns_token:''})
const reverseForm=ref({id:'',domain:'',upstream:'http://127.0.0.1:3000',certificate_id:'',enabled:false,version:0})
const compatible=computed(()=>templates.value.filter(t=>t.engines?.includes(form.value.engine)))
const activeTemplate=computed(()=>templates.value.find(t=>t.kind===form.value.kind))
const needsTLS=computed(()=>activeTemplate.value?.certificate&&!(form.value.kind==='vmess'&&form.value.tls_mode==='none'))
const websocket=computed(()=>['vless','vmess','trojan'].includes(form.value.kind))
const filtered=computed(()=>services.value.filter(s=>!hostFilter.value||s.host_id===hostFilter.value))
const hops=computed(()=>services.value.filter(s=>s.id!==editing.value&&!['frps','frpc'].includes(s.kind)&&(form.value.engine!=='xray'||['shadowsocks','vless','vmess','trojan'].includes(s.kind))))
let hydrating=false
let alive=true,timer:ReturnType<typeof setTimeout>
onUnmounted(()=>{alive=false;clearTimeout(timer);form.value.private_key='';certForm.value.dns_token=''})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
async function reload(){const data=await Promise.all(['live','nodes','protocol-templates','certificates','reverse-proxies','engine-catalog'].map(p=>props.api(p)));if(!alive)return;[services.value,nodes.value,templates.value,certificates.value,proxies.value,catalog.value]=data}
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden'&&!busy.value&&!showForm.value)await action(reload);if(alive)schedule()},20000)}
onMounted(()=>{void action(reload);schedule()})
watch(()=>form.value.engine,()=>{if(hydrating)return;if(!compatible.value.some(t=>t.kind===form.value.kind)&&form.value.engine!=='frp')form.value.kind=compatible.value[0]?.kind??'shadowsocks';if(form.value.engine==='frp')form.value.kind='frps';form.value.node_id=''})
watch(()=>form.value.kind,()=>{if(hydrating)return;form.value.transport='tcp';form.value.path='';form.value.tls_mode='tls';form.value.certificate='';form.value.private_key='';form.value.next_id=''})
watch(()=>form.value.certificate_id,id=>{const c=certificates.value.find(c=>c.id===id);if(c)form.value.server_name=c.domain})
function create(){editing.value='';form.value=fresh();form.value.host_id=hostFilter.value;preview.value=null;showForm.value=true}
async function edit(row:Row){await action(async()=>{const detail=await props.api('live/'+row.id);hydrating=true;editing.value=row.id;form.value={...fresh(),...detail.spec,password:'',uuid:'',name:detail.name,host_id:detail.host_id,node_id:detail.node_id,certificate_id:detail.certificate_id,next_id:detail.next_id,version:detail.version,engine:['frps','frpc'].includes(detail.spec.kind)?'frp':detail.spec.engine||'sing-box',transport:detail.spec.transport||'tcp',tls_mode:detail.spec.tls_mode||'tls',certificate:'',private_key:'',rotate_credentials:false};preview.value=detail.rendered;await nextTick();hydrating=false;showForm.value=true})}
function save(){void action(async()=>{const fields=['password','uuid','name','host_id','node_id','engine','kind','address','listen','port','transport','path','tls_mode','server_name','certificate_id','certificate','private_key','next_id','parent_id','tunnels'];if(editing.value)fields.push('version','rotate_credentials');const payload=Object.fromEntries(fields.map(k=>[k,(form.value as Row)[k]]));if(form.value.engine==='frp'){delete payload.engine;payload.transport='';payload.tls_mode=''};if(!websocket.value){payload.transport='';payload.path=''};if(!needsTLS.value){payload.server_name='';payload.certificate='';payload.private_key='';payload.certificate_id='';if(form.value.kind!=='vmess')payload.tls_mode=''};await props.api('live'+(editing.value?'/'+editing.value:''),editing.value?'PUT':'POST',payload);form.value.private_key='';form.value.certificate='';form.value.password='';form.value.uuid='';showForm.value=false;await reload();emit('changed');notice.value=editing.value?'配置版本已保存，等待 Agent 原生检查与回报':'已创建逻辑节点部署，默认停用'})}
function toggle(row:Row){confirm.value={...row,operation:'toggle'}}
function requestCert(){confirm.value={operation:'certificate',name:certForm.value.domain}}
function saveReverse(){confirm.value={operation:'reverse',name:reverseForm.value.domain}}
function confirmAction(){const c=confirm.value;if(!c)return;confirm.value=null;void action(async()=>{if(c.operation==='toggle')await props.api('live/'+c.id+'/toggle','POST',{enabled:!c.enabled});if(c.operation==='certificate'){await props.api('certificates','POST',{...certForm.value});certForm.value.dns_token='';notice.value='证书请求已排队；HTTP-01 需要域名指向总管理网关且 80 端口可达。后台负责自动续期。'}if(c.operation==='reverse'){const {id,...payload}=reverseForm.value;await props.api('reverse-proxies'+(id?'/'+id:''),id?'PUT':'POST',payload);notice.value='反代设置已保存，等待网关检查并回报'}await reload();emit('changed')})}
function retry(c:Row){void action(async()=>{await props.api('certificates/'+c.id+'/retry','POST',{});await reload()})}
function editReverse(row:Row){reverseForm.value={id:row.id,domain:row.domain,upstream:row.upstream,certificate_id:row.certificate_id,enabled:row.enabled,version:row.version}}
function hostName(id:string){return props.hosts.find(h=>h.id===id)?.name??id.slice(0,8)}
function chain(row:Row){const names=[row.name],seen=new Set([row.id]);let next=row.next_id;while(next&&names.length<8){const n=services.value.find(s=>s.id===next);if(!n||seen.has(next)){names.push('引用异常');break};names.push(n.name);seen.add(next);next=n.next_id}return names.join(' → ')+(next?'':' → 直连出口')}
</script>
<template>
<section class="topology-workspace">
 <div class="topology-flow"><span>01 主机</span><b>→</b><span>02 内核实例</span><b>→</b><span>03 协议入站 / 出站</span><b>→</b><span>04 链式 / 反代</span><b>→</b><span>05 客户端订阅</span></div>
 <nav class="topology-tabs" aria-label="节点配置分类"><button v-for="item in [{id:'nodes',name:'主机与逻辑节点'},{id:'certificates',name:'免费证书'},{id:'reverse',name:'反向代理'},{id:'catalog',name:'内核兼容目录'}]" :key="item.id" :class="['secondary',{active:tab===item.id}]" @click="tab=item.id">{{item.name}}</button></nav>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="form-note" role="status">{{notice}}</p>
 <section v-if="tab==='nodes'" class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">HOST / KERNEL / LOGICAL NODE</span><h2>逻辑节点与入站出站</h2></div><button class="primary" :disabled="busy" @click="create">新建节点部署</button></div>
 <p class="muted">每条部署属于一台主机及一个逻辑节点，使用指定内核运行一个入站和一个出站。相同逻辑节点可部署到多台主机。FRP 是独立穿透服务。未启用实例不启动引擎。</p>
 <label>筛选运行主机<select v-model="hostFilter"><option value="">所有主机</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}} · Agent {{h.agent_version||'未连接'}}</option></select></label>
 <div class="table-scroll"><table><thead><tr><th>主机 / 逻辑节点</th><th>内核 → 协议入站</th><th>出站链路</th><th>运行状态</th><th>配置</th></tr></thead><tbody><tr v-for="s in filtered" :key="s.id"><td>{{s.name}}<small class="block-muted">{{hostName(s.host_id)}} · {{nodes.find(n=>n.id===s.node_id)?.name||'自动节点'}}</small></td><td>{{['frps','frpc'].includes(s.kind)?'FRP':s.engine}} → {{s.kind}}<small class="block-muted">{{s.address}} : {{s.port}}</small></td><td>{{chain(s)}}</td><td><span :class="['status',s.online?'succeeded':'pending']">{{s.online?'运行中':s.enabled?s.state:'停用'}}</span><small class="block-muted">版本 {{s.reported_version}} / {{s.version}}</small></td><td><button class="text-button" :disabled="busy" @click="edit(s)">详情 / 编辑</button><button class="text-button" :disabled="busy" @click="toggle(s)">{{s.enabled?'停用':'启用'}}</button></td></tr></tbody></table></div><p v-if="!filtered.length" class="muted">先在主机资产连接 Agent，再创建内核与协议部署。</p></section>
 <section v-if="tab==='certificates'" class="panel publish-card"><span class="eyebrow">ACME / LET'S ENCRYPT</span><h2>免费证书与自动续期</h2><p class="muted">证书按域名管理，节点通过引用自动接收续期版本。HTTP-01：域名 A/AAAA 指向总管理网关，公网 TCP 80 可达。DNS-01：Cloudflare 托管域名可使用最小权限 DNS 编辑令牌，不要求节点有公网 IPv4。通配符暂不接受。</p><form @submit.prevent="requestCert"><div class="fields"><label>证书域名<input v-model="certForm.domain" required placeholder="proxy.example.com"></label><label>到期通知邮箱<input v-model="certForm.email" type="email" required></label><label>验证方式<select v-model="certForm.provider"><option value="http-01">HTTP-01 · 总管理网关</option><option value="cloudflare">DNS-01 · Cloudflare</option></select></label><label v-if="certForm.provider==='cloudflare'">DNS API 令牌<input v-model="certForm.dns_token" type="password" autocomplete="off" required></label></div><button class="primary" :disabled="busy">免费一键申请</button></form><div class="table-scroll"><table><thead><tr><th>域名</th><th>验证</th><th>状态 / 到期</th><th>操作</th></tr></thead><tbody><tr v-for="c in certificates" :key="c.id"><td>{{c.domain}}</td><td>{{c.provider}}</td><td>{{c.state}}<small class="block-muted">{{c.expires_at?new Date(c.expires_at).toLocaleDateString():'等待签发'}} {{c.result}}</small></td><td><button class="text-button" :disabled="busy||['pending','running'].includes(c.state)" @click="retry(c)">重新申请 / 检查续期</button></td></tr></tbody></table></div></section>
 <section v-if="tab==='reverse'" class="panel publish-card"><span class="eyebrow">HTTPS GATEWAY / REVERSE PROXY</span><h2>反向代理配置</h2><p class="muted">总管理网关的 HTTPS 域名反代到本机 HTTP 应用或 FRP 映射端口，支持 WebSocket 升级。域名不能覆盖管理域名。代理协议的链式出站请在节点配置中设置。</p><form @submit.prevent="saveReverse"><div class="fields"><label>反代域名<input v-model="reverseForm.domain" :readonly="!!reverseForm.id" required></label><label>上游 HTTP 地址<input v-model="reverseForm.upstream" required placeholder="http://127.0.0.1:3000"></label><label>域名证书<select v-model="reverseForm.certificate_id" required><option value="" disabled>先在免费证书中申请</option><option v-for="c in certificates" :key="c.id" :value="c.id">{{c.domain}} · {{c.state}}</option></select></label><label class="check-label"><input v-model="reverseForm.enabled" type="checkbox">启用反代公网入口</label></div><button class="primary" :disabled="busy">{{reverseForm.id?'保存反代修改':'创建反代配置'}}</button><button v-if="reverseForm.id" class="secondary" type="button" @click="reverseForm={id:'',domain:'',upstream:'http://127.0.0.1:3000',certificate_id:'',enabled:false,version:0}">取消编辑</button></form><div class="table-scroll"><table><thead><tr><th>域名</th><th>上游</th><th>网关状态</th><th>操作</th></tr></thead><tbody><tr v-for="p in proxies" :key="p.id"><td>{{p.domain}}</td><td>{{p.upstream}}</td><td>{{p.enabled?'启用':'停用'}} · {{p.state}} · {{p.reported_version}}/{{p.version}}</td><td><button class="text-button" @click="editReverse(p)">编辑反代</button></td></tr></tbody></table></div></section>
 <section v-if="tab==='catalog'" class="panel publish-card"><span class="eyebrow">ENGINE CAPABILITIES / 2026-10-23</span><h2>内核能力与平台实现范围</h2><p class="muted">按官方文档列出入站和出站，区分“内核文档支持”与“本平台已实现”。文档中新能力可能要求不同版本或构建选项。传输层 TCP、WebSocket、gRPC、XHTTP 与 TLS、REALITY 不等于代理协议；当前编辑器支持 TCP / WebSocket，尚未开放其他组合。</p><div class="table-scroll"><table><thead><tr><th>内核</th><th>协议 / 功能</th><th>入站</th><th>出站</th><th>平台模板</th></tr></thead><tbody><tr v-for="c in catalog" :key="c.engine+c.protocol"><td>{{c.engine}} {{c.pinned_version}}</td><td><a :href="c.source" target="_blank" rel="noreferrer">{{c.protocol}}</a></td><td>{{c.inbound?'有':'—'}}</td><td>{{c.outbound?'有':'—'}}</td><td>{{c.status}}</td></tr></tbody></table></div></section>
 <div v-if="showForm" class="modal-backdrop" @keydown.esc="showForm=false"><form class="modal topology-editor" role="dialog" aria-modal="true" aria-labelledby="node-editor-title" @submit.prevent="save"><div class="modal-heading"><div><span class="eyebrow">{{editing?'VERSIONED CONFIGURATION':'NEW DEPLOYMENT'}}</span><h2 id="node-editor-title">{{editing?'节点详情与配置编辑':'主机 → 内核 → 协议'}}</h2></div><button class="secondary" type="button" @click="showForm=false;form.private_key=''">关闭</button></div><div class="form-content"><p v-if="error" class="error">{{error}}</p><div class="fields"><label>运行主机<select v-model="form.host_id" :disabled="!!editing" required><option value="" disabled>选择主机</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>内核<select v-model="form.engine"><option value="sing-box">sing-box 1.14.3</option><option value="xray">Xray 26.10.21</option><option v-if="!editing" value="frp">FRP 穿透</option></select></label><label>逻辑节点分组<select v-model="form.node_id"><option value="">按此部署名称新建逻辑节点</option><option v-for="n in nodes.filter(n=>n.engine===form.engine)" :key="n.id" :value="n.id">{{n.name}}</option></select></label><label>部署名称<input v-model="form.name" required maxlength="100"></label><label>入站协议<select v-model="form.kind" :disabled="!!editing"><template v-if="form.engine!=='frp'"><option v-for="t in compatible" :key="t.kind" :value="t.kind">{{t.name}}</option></template><template v-else><option value="frps">FRP 服务端</option><option value="frpc">FRP 客户端</option></template></select></label><label v-if="websocket">传输层<select v-model="form.transport"><option value="tcp">TCP</option><option value="ws">WebSocket</option></select></label><label v-if="form.transport==='ws'">WebSocket 路径<input v-model="form.path" required placeholder="/proxy"></label><label v-if="form.kind==='vmess'">传输安全<select v-model="form.tls_mode"><option value="tls">TLS · 需要证书</option><option value="none">VMess AEAD · 不使用外层 TLS</option></select></label></div><h3>身份凭据（只写）</h3><div class="fields"><label>代理密码<input v-model="form.password" type="password" autocomplete="off" placeholder="留空随机生成 / 编辑时保留当前密码"></label><label v-if="['vless','vmess','tuic'].includes(form.kind)">UUID<input v-model="form.uuid" autocomplete="off" placeholder="留空随机生成 / 编辑时保留当前 UUID"></label></div><p class="muted">密码需为 32 字节的 Base64 编码；已有密码和私钥不会回显。修改凭据后客户端需更新订阅。</p><h3>入站监听与分享地址</h3><div class="fields"><label>客户端连接地址<input v-model="form.address" :required="form.kind!=='frpc'" placeholder="域名、IPv4 或 IPv6"></label><label>监听地址<select v-model="form.listen"><option>127.0.0.1</option><option>::1</option><option>0.0.0.0</option><option>::</option></select></label><label>监听端口<input v-model.number="form.port" type="number" min="1024" max="65535" required></label></div><p class="muted">监听地址是主机绑定地址；客户端连接地址必须从客户端网络可达。HY2/TUIC 使用 UDP。默认回环监听不提供公网入口。</p>
 <template v-if="needsTLS"><h3>TLS 与证书</h3><div class="fields"><label>受管证书<select v-model="form.certificate_id"><option value="">手动 PEM {{editing?'（留空保留当前证书）':''}}</option><option v-for="c in certificates.filter(c=>c.state==='ready')" :key="c.id" :value="c.id">{{c.domain}} · 自动续期</option></select></label><label>服务器名 SNI<input v-model="form.server_name" required placeholder="proxy.example.com"></label><template v-if="!form.certificate_id"><label>证书 fullchain PEM<textarea v-model="form.certificate" :required="!editing" autocomplete="off"></textarea></label><label>私钥 PEM<textarea v-model="form.private_key" :required="!editing" autocomplete="off"></textarea></label></template></div><button class="text-button" type="button" @click="showForm=false;tab='certificates';certForm.domain=form.server_name">前往免费一键申请证书</button></template>
 <template v-if="form.engine!=='frp'"><h3>出站与链式代理</h3><div class="fields"><label>出站方式<select v-model="form.next_id"><option value="">直接访问目标</option><option v-for="n in hops" :key="n.id" :value="n.id">下一跳：{{n.name}} · {{n.engine}} / {{n.kind}}</option></select></label><label v-if="editing" class="check-label"><input v-model="form.rotate_credentials" type="checkbox">轮换此节点代理凭据（已有客户端需更新订阅）</label></div><p class="muted">客户端 → 当前入站 → 下一跳节点 → 后续节点 → 目标。最多 8 跳，拒绝环路；下一跳凭据或证书更新后自动同步。Xray 出站仅开放已验证的 SS / VLESS / VMess / Trojan 组合。</p></template>
 <template v-else><label v-if="form.kind==='frpc'">关联 FRP 服务端<select v-model="form.parent_id" required><option value="">选择服务端</option><option v-for="s in services.filter(s=>s.kind==='frps')" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button v-if="form.kind==='frps'" type="button" class="secondary" @click="form.tunnels.push({name:'tunnel-'+(form.tunnels.length+1),local_host:'127.0.0.1',local_port:3000,remote_port:30000})">添加 FRP TCP 隧道</button><div v-for="(t,i) in form.tunnels" :key="i" class="fields"><label>隧道名<input v-model="t.name" required></label><label>本地端口<input v-model.number="t.local_port" type="number" required></label><label>中继映射端口<input v-model.number="t.remote_port" type="number" required></label><button type="button" @click="form.tunnels.splice(i,1)">移除</button></div></template>
 <details v-if="preview"><summary>查看生成的完整入站 / 出站配置（凭据已隐藏）</summary><pre class="config-preview">{{JSON.stringify(preview,null,2)}}</pre></details><p v-if="editing" class="muted">当前版本 {{form.version}}。保存采用版本冲突检查；Agent 原生检查通过后才切换。主机和协议不可直接替换，请新建部署后更新订阅。</p></div><div class="modal-footer"><button class="secondary" type="button" @click="showForm=false">取消</button><button class="primary" :disabled="busy||form.engine==='frp'&&!!editing">{{editing?'保存配置新版本':'创建并保持停用'}}</button></div></form></div>
 <div v-if="confirm" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="topology-confirm"><div class="modal-heading"><h2 id="topology-confirm">确认{{confirm.operation==='toggle'?(confirm.enabled?'停止服务':'启动真实服务'):confirm.operation==='certificate'?'申请免费证书':'保存反代设置'}}</h2></div><div class="form-content"><p>{{confirm.name}}</p><p v-if="confirm.operation==='certificate'">将通过 Let's Encrypt 免费签发并自动续期；使用其服务即同意当前订户协议。请确认域名控制权与验证配置。</p><p v-else-if="confirm.operation==='reverse'">启用后此域名会公开访问选定上游应用。Nginx 校验通过后才回报生效。</p><p v-else>请确认监听地址及业务端口防火墙。Agent 将在下一次同步执行。</p></div><div class="modal-footer"><button class="secondary" @click="confirm=null">取消</button><button class="primary" @click="confirmAction">确认执行</button></div></section></div>
</section>
</template>
<style scoped>
.topology-flow,.topology-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 20px}.topology-flow{padding:18px;border:1px solid var(--border);border-radius:14px;font-size:12px;color:var(--muted)}.topology-flow b{opacity:.4}.topology-tabs .active{border-color:var(--accent);color:var(--accent)}.topology-editor{width:min(1000px,95vw);max-height:92vh;display:flex;flex-direction:column}.topology-editor .form-content{overflow:auto}.config-preview{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);padding:16px;max-height:350px;overflow:auto;font-size:12px}h3{margin:24px 0 14px}.topology-workspace select{max-width:100%}@media(max-width:640px){.topology-tabs button{flex:1;min-width:42%}.topology-flow{gap:6px;padding:12px}.topology-editor{width:100vw;max-height:96dvh}.topology-editor .fields{grid-template-columns:1fr}}
</style>
